import {pieces,colors,mapAlg} from '../../src/lib/cube';
import {routines} from './policy';
import type {CubeData,JevRequest,JevResponse} from '../../src/lib/types';
export type Ask=(r:JevRequest)=>Promise<JevResponse>;
const sides=['F','R','B','L'];
const corners:Record<string,string>={FR:'DRF',BR:'DBR',BL:'DLB',FL:'DFL'};
const cornerSlots=['UFR','URB','UBL','ULF','DRF','DBR','DLB','DFL'];
const edgeSlots=['UF','UR','UB','UL','DF','DR','DB','DL','FR','BR','BL','FL'];
export function view(state:CubeData,target:string,front:string){
 const all=pieces(state),c=all.find(p=>p.piece===corners[target])!,e=all.find(p=>p.piece===target)!;
 const local=(f:string)=>{const i=sides.indexOf(f);return i<0?f:sides[(i-sides.indexOf(front)+4)%4];};
 const position=(p:string,slots:string[])=>slots.find(s=>[...s].sort().join('')===[...p].map(local).sort().join(''))!;
 const dir=(p:typeof c,color:string)=>p.stickers[color]?local(p.stickers[color]):'absent';
 const right=sides[(sides.indexOf(front)+1)%4];
 return {corner:{position:position(c.position,cornerSlots),downColorDirection:dir(c,'yellow'),frontColorDirection:dir(c,colors[front]),rightColorDirection:dir(c,colors[right])},edge:{position:position(e.position,edgeSlots),frontColorDirection:dir(e,colors[front]),rightColorDirection:dir(e,colors[right])}};
}
const turnCriteria={U:'Upper edges UF→UL→UB→UR→UF; upper corners UFR→ULF→UBL→URB→UFR.',"U'":'Upper edges UF→UR→UB→UL→UF; upper corners UFR→URB→UBL→ULF→UFR.',U2:'Upper edges UF/UB and UR/UL exchange; upper corners UFR/UBL and URB/ULF exchange.',reconsider:'No U rotation is needed or these positions cannot be related by U.'};
export async function decide(state:CubeData,ask:Ask,previousTarget:string|null=null,recentActions:string[]=[]){
 const all=pieces(state);const pairs=Object.entries(corners).map(([id,corner])=>({id,corner:all.find(p=>p.piece===corner),edge:all.find(p=>p.piece===id)}));
 const targetAnswer=await ask({model:'jev-1.13.0',state:{pairs,previousTarget,recentActions:recentActions.slice(-2)},questions:{target:{type:'choice',instructions:'Choose an unfinished corner/edge pair to solve together, preserving the cross and completed pairs. Continue previousTarget until both pieces are solved. Otherwise prefer pieces already in the upper layer. Each ID is a home slot, not a current location. Choose done only when every listed corner and edge is solved.',criteria:{...Object.fromEntries(Object.keys(corners).map(k=>[k,`Work on pair ${k}, if its corner or edge is not solved.`])),done:'All four pairs have both corner.solved=true and edge.solved=true.'}}}});
 const target=targetAnswer.answers.target.choice;if(target==='done')return {target,alg:'',action:'done'};
 const selected=pairs.find(p=>p.id===target)!;
 const ref=await ask({model:'jev-1.13.0',state:{homeSlot:target,corner: selected.corner,edge:selected.edge},questions:{front:{type:'choice',instructions:'Choose a notation reference that puts this pair HOME at local front-right. This changes notation only, not the cube. Use homeSlot, not its current position.',criteria:{F:'Home FR becomes local front-right.',R:'Home BR becomes local front-right.',B:'Home BL becomes local front-right.',L:'Home FL becomes local front-right.'}}}});
 const front=ref.answers.front.choice,pair=view(state,target,front);
 const prep=await ask({model:'jev-1.13.0',state:pair,questions:{preparation:{type:'choice',instructions:'Choose how to prepare the selected pair for its learned F2L reference. First free any target piece trapped in a different bottom/middle slot. Preserve completed slots. With both targets in the upper layer or their own slot, use the canonical reference positions in these options.',criteria:{'extract-corner':'Corner is in a bottom position other than DRF. Lift it from its CURRENT slot.','extract-edge':'Corner is upper or DRF, but edge is in a middle position other than FR. Lift the edge from its CURRENT slot.','align-corner':'Corner is upper but not UFR, and edge is upper or FR. Rotate U so the corner reaches UFR.','align-edge':'Corner is DRF and edge is upper but not UF. Rotate U so the edge reaches UF.',routine:'Corner is UFR and edge is upper or FR; OR corner is DRF and edge is UF or FR. The pair is prepared for a learned routine.',reconsider:'None of these reference domains applies.'}}}});
 const preparation=prep.answers.preparation.choice;
 if(preparation==='routine'){
  const a=await ask({model:'jev-1.13.0',state:{...pair,frame:'Local front F, right R, down D. Target pair belongs at DRF corner and FR edge.'},questions:{routine:{type:'choice',instructions:'Choose a learned F2L routine whose reference illustration matches BOTH observed pieces: their current positions and sticker directions. Read current position, not the destination slot. These routines solve this corner and edge together, preserving the cross and other three pairs. Do not simulate candidate outcomes. If no reference matches choose reconsider.',criteria:{...Object.fromEntries(routines.map(r=>[r.id,r.description])),reconsider:'No listed illustration matches both pieces.'}}}});
  const action=a.answers.routine.choice;return {target,front,preparation,action,alg:mapAlg(routines.find(r=>r.id===action)?.alg??'',front)};
 }
 if(preparation==='align-corner'||preparation==='align-edge'){
  const source=preparation==='align-corner'?pair.corner.position:pair.edge.position,destination=preparation==='align-corner'?'UFR':'UF';
  const a=await ask({model:'jev-1.13.0',state:{currentPosition:source,requiredPosition:destination},questions:{turn:{type:'choice',instructions:'Choose the U turn carrying currentPosition to requiredPosition using the generic position cycles. Choose one rotation, not a routine.',criteria:turnCriteria}}});const action=a.answers.turn.choice;return {target,front,preparation,action,alg:action==='reconsider'?'':action};
 }
 if(preparation==='extract-corner'||preparation==='extract-edge'){
  const a=await ask({model:'jev-1.13.0',state:{currentPosition:preparation==='extract-corner'?pair.corner.position:pair.edge.position},questions:{extraction:{type:'choice',instructions:'Choose the slot-opening routine that lifts the target from its CURRENT position. These routines restore the cross and the other three pair slots. Only the opened slot is disturbed. Coordinates are in the selected local frame.',criteria:Object.fromEntries(sides.map((f,i)=>[f,`Opens local slot ${['FR','BR','BL','FL'][i]} and bottom corner ${['DRF','DBR','DLB','DFL'][i]}. Execute ${mapAlg("R U R'",f)}.`]))}}});const action=a.answers.extraction.choice;return {target,front,preparation,action:'extract@'+action,alg:mapAlg(mapAlg("R U R'",action),front)};
 }
 return {target,front,preparation,action:'reconsider',alg:''};
}

sources.controller-v3:
import {decide as original,type Ask} from './controller';
import type {CubeData} from '../../src/lib/types';
export async function decide(state:CubeData,ask:Ask,previousTarget:string|null=null,recentActions:string[]=[]){
 return original(state,async request=>{
  if(request.questions.preparation){request=structuredClone(request);const s=request.state as any,c=s.corner.position,e=s.edge.position;
   // Geometric observations only. No option, applicability score or predicted outcome.
   request.state={corner:{layer:c.includes('U')?'upper':'bottom',atDRF:c==='DRF',atUFR:c==='UFR'},edge:{layer:e.includes('U')?'upper':'middle',atFR:e==='FR',atUF:e==='UF'}};
   request.questions.preparation.instructions='Choose the preparation from these geometric observations in the selected local frame. DRF is the destination corner slot, FR the destination edge slot. Test extraction before alignment or choosing a routine. Both pieces must satisfy a routine reference.';
   request.questions.preparation.criteria={
    'extract-corner':'corner.layer=bottom and corner.atDRF=false.',
    'extract-edge':'corner is upper or atDRF=true; edge.layer=middle and edge.atFR=false.',
    'align-corner':'corner.layer=upper and corner.atUFR=false; edge is upper or atFR=true.',
    'align-edge':'corner.atDRF=true; edge.layer=upper and edge.atUF=false.',
    routine:'Either (corner.atUFR=true AND (edge.layer=upper OR edge.atFR=true)), OR (corner.atDRF=true AND (edge.atUF=true OR edge.atFR=true)).',
    reconsider:'No combination above applies.'
   };
  }return ask(request);
 },previousTarget,recentActions);
}

sources.preparation-screen-v2:
// Isolated request test: target and frame are supplied by the fixture, not model-scored.
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {solved,pieces} from '../../src/lib/cube';
import {decide as baseline} from './controller';
import {decide as compact} from './controller-v3';
import {createRun} from '../../src/server/runner';
import {evaluate,budget} from '../../src/server/jev';
import {db,saveRun,getRun} from '../../src/server/store';
import type {JevRequest,JevResponse,CubeData} from '../../src/lib/types';
const phase=process.argv[2]??'development';if(!['development','validation'].includes(phase))throw Error('Bad phase');
const dir='experiments/f2l-efficiency-v1/preparation-round2',split='f2l-preparation-v2';mkdirSync(dir,{recursive:true});
const variants=['compact'];
writeFileSync(`${dir}/${phase}-started.json`,JSON.stringify({at:new Date().toISOString(),sources:Object.fromEntries(['controller','controller-v3','preparation-screen-v2'].map(n=>[n,readFileSync(`scripts/f2l-efficiency-v1/${n}.ts`,'utf8')])),limits:{calls:150,dollars:.02,concurrency:2},budgetBefore:budget()},null,2),{flag:'wx'});
const fixtures:{id:string;state:CubeData;expected:string}[]=[];const base=await solved();
for(let c=0;c<8;c++)for(const e of [0,1,2,3,8,9,10,11]){
 const index=c*8+[0,1,2,3,8,9,10,11].indexOf(e);if((index%2===0)!==(phase==='development'))continue;
 const s=structuredClone(base);[s.CORNERS.pieces[c],s.CORNERS.pieces[4]]=[s.CORNERS.pieces[4],s.CORNERS.pieces[c]];[s.EDGES.pieces[e],s.EDGES.pieces[8]]=[s.EDGES.pieces[8],s.EDGES.pieces[e]];
 if((c!==4)!==(e!==8)){const others=[0,1,2,3].filter(i=>i!==e);[s.EDGES.pieces[others[0]],s.EDGES.pieces[others[1]]]=[s.EDGES.pieces[others[1]],s.EDGES.pieces[others[0]]];}
 const cp=pieces(s).find(p=>p.piece==='DRF')!.position,ep=pieces(s).find(p=>p.piece==='FR')!.position;
 const expected=!cp.includes('U')&&cp!=='DRF'?'extract-corner':!ep.includes('U')&&ep!=='FR'?'extract-edge':cp.includes('U')&&cp!=='UFR'?'align-corner':cp==='DRF'&&ep.includes('U')&&ep!=='UF'?'align-edge':'routine';
 fixtures.push({id:`position-${index}`,state:s,expected});
}
writeFileSync(`${dir}/${phase}-fixtures.json`,JSON.stringify(fixtures,null,2));
const usage=()=>db.query("SELECT COUNT(*) requests,COALESCE(SUM(amount),0) cost FROM ledger l JOIN runs r ON l.run_id=r.id WHERE json_extract(r.json,'$.split')=?").get(split) as {requests:number;cost:number};
const rows:any[]=[];const persist=()=>writeFileSync(`${dir}/${phase}-results.json`,JSON.stringify({phase,rows,usage:usage()},null,2));
const jobs=variants.flatMap(variant=>fixtures.map(f=>({variant,f})));let cursor=0;
async function job({variant,f}:typeof jobs[number]){
 let request:JevRequest|undefined;const stop=new Error('captured');
 try{await (variant==='baseline'?baseline:compact)(f.state,async r=>{if(r.questions.preparation){request=r;throw stop;}const [key,value]=r.questions.target?['target','FR']:['front','F'];return {model:'jev-1.13.0',usage:{input_tokens:0,output_tokens:0},answers:{[key]:{type:'choice',choice:value,probabilities:{[value]:1},confidence:1}}} as JevResponse;});}catch(e){if(e!==stop)throw e;}
 if(!request)throw Error('No preparation request');const run=await createRun('','skills',split);saveRun({...run,state:f.state});const row:any={id:f.id,variant,runId:run.id,expected:f.expected,status:'running'};rows.push(row);persist();
 try{for(let retry=0;retry<3;retry++){const u=usage();if(u.requests>=150||u.cost+.002688>.02||budget().reservedAndSpent+.002688>9)throw Error('Budget cap');try{row.exchange=await evaluate(run.id,request,AbortSignal.timeout(30000),{maxAttempts:1});break;}catch(e){if(retry===2||!/(HTTP (429|5\d\d)|network)/i.test(String(e)))throw e;row.transportErrors??=[];row.transportErrors.push(String(e));await new Promise(r=>setTimeout(r,1000*2**retry));}}row.choice=row.exchange.response.answers.preparation.choice;row.passed=row.choice===f.expected;row.status='complete';}catch(e){row.status='error';row.error=String(e);row.passed=false;}saveRun({...getRun(run.id),status:'stopped',reason:'Preparation component test'});persist();
}
await Promise.all(Array.from({length:2},async()=>{while(cursor<jobs.length)await job(jobs[cursor++]);}));console.log({usage:usage(),scores:variants.map(v=>({variant:v,passed:rows.filter(r=>r.variant===v&&r.passed).length,n:rows.filter(r=>r.variant===v).length}))});
